            a: 'Gorillaz feat. De La Soul — «Feel Good Inc.» (2005). Принимается: «Горилаз — Фил Гуд Инк»; De La Soul называть не обязательно',
            c: 'Дэймон Албарн сочинил песню по дороге на фестиваль Coachella: «потрясающая долина ветряков» дала припев про мельницу — и остров с ветряком в клипе. В Британии правила требовали физический релиз, поэтому выпустили 300 пластинок-«пикчер-дисков». «Грэмми» 2006 — за лучшее вокальное сотрудничество. Рисованные музыканты хороши тем, что не опаздывают на репетицию и не пьют пиво на сцене. Вам этого не понять.',
