            a: '«Бриллиантовая рука» (1968, реж. Леонид Гайдай) — закадровый голос: «Дальше следует непереводимая игра слов с использованием местных идиоматических выражений»',
            c: 'Когда герои на «турецком» рынке обмениваются паролем «Чёрт побери!», переводчик за кадром сдаётся — дальше только непереводимая игра слов. Фильм посмотрели около 76 миллионов зрителей, он стал лидером проката 1969 года. Так что, если за столом начнётся «игра слов» — не переводим.',
