            q: 'Угадай фильм по опенингу. Действие там происходит в ноябре 2019-го — то есть уже в прошлом, а летающих машин нам так и не выдали. Что за фильм?',
            a: '«Бегущий по лезвию» (Blade Runner, 1982, реж. Ридли Скотт; музыка Вангелиса, «Main Titles»; принимается: Blade Runner)',
            c: 'Музыку Вангелис играл на синтезаторе Yamaha CS-80, а официальный саундтрек вышел на CD только в 1994-м — через 12 лет после фильма. Фильм снят по Филипу Дику; в реальном 2019-м вместо репликантов у нас были голосовые помощники, не понимавшие, о чём мы просим.',
