            c: 'Фильм «тормозили» из-за обилия тюремного жаргона, пока его не посмотрел Брежнев — и разрешил: эти словечки и так знает любой мальчишка. В 1972-м фильм стал лидером проката (65,2 млн зрителей). Рекомендуем остановиться на второй части формулы — на «выпил».',
