            c: '«Ещё на одну минуту» звучит в конце 10-й серии, а вопрос про пастора — уже в 11-й: в августе 1973-го миллионы зрителей (по оценкам, 50–80 млн) честно ждали продолжения — стриминга-то не было. Штирлиц, к слову, ответил невозмутимо: «Вот с этого и надо было начинать». А Броневой говорил, что, знай он, каким был настоящий Мюллер (худой горбоносый брюнет), скорее всего отказался бы от роли. Повезло всей стране.',
